const articleSections: ArticleSection[] = [
  {
    id: 'orientation',
    title: 'A field in the plural',
    paragraphs: [
      p('fem-orientation-1', 'Feminist philosophy is not a doctrine shared by everyone who uses the name. It is a field of arguments and practices that examines gendered oppression, the exclusions built into philosophical concepts and institutions, and possibilities for more just forms of knowledge, agency, relationship, and collective life. Some work begins with women’s subordination; some analyzes gender beyond a binary; some centers the interaction of gender with race, class, sexuality, disability, nationality, coloniality, or other structures. The field’s internal disagreements are part of its philosophy, not an editorial inconvenience.', [c('fem-overview-sep', 'section', '1. What is Feminism?; 2. Feminist Scholarship'), c('fem-politics-sep', 'section', '2. Contemporary Approaches and Debates')]),
      p('fem-orientation-2', 'Feminist philosophers work in ethics, political philosophy, epistemology, philosophy of science, metaphysics, language, law, religion, aesthetics, history of philosophy, and many other areas. They also build questions that canonical classifications often ignored: care, dependency, embodiment, objectification, reproductive labor, sexual violence, family, disability, and the politics of knowledge. Analytic, continental, pragmatist, phenomenological, Marxist, decolonial, Indigenous, Black feminist, trans feminist, and other methods can overlap or conflict. No single list is exhaustive or culturally neutral.', [c('fem-overview-sep', 'section', '3. Approaches; 4. Interventions; 5. Topics'), c('fem-politics-sep', 'section', '2. Contemporary Approaches and Debates')]),
    ],
  },
  {
    id: 'genealogies',
    title: 'Genealogies instead of one origin',
    paragraphs: [
      p('fem-genealogy-1', 'Arguments now read as feminist long predate the English word “feminism.” Mary Wollstonecraft’s 1792 Vindication criticizes an educational and social order that denies women the development expected of rational moral agents. Her work is a major European landmark, not the universal birth of feminist thought. It addresses particular class and national contexts, retains some assumptions later feminists reject, and belongs beside other histories of resistance, writing, organizing, and oral transmission rather than at the head of a single worldwide line.', [c('fem-wollstonecraft', 'chapter', 'Introduction; chapters 2, 5, and 12'), c('fem-overview-sep', 'section', '1. What is Feminism?'), c('fem-latin-american-sep', 'section', '1. History: A Genealogy')]),
      p('fem-genealogy-2', 'Contemporary feminist philosophy became more visible as an academic field in the 1970s, when philosophers shaped by liberation movements turned established methods toward gendered experience and exclusion and also created journals, courses, and professional associations. That institutional history should not erase earlier women philosophers or political thought outside departments, nor should it imply that feminism entered every region through the same route. Latin American and Caribbean genealogies, for example, must be understood through colonialism, enslavement, Indigenous marginalization, dictatorship, religion, and regionally specific movements.', [c('fem-overview-sep', 'section', '2. Feminist Scholarship'), c('fem-ethics-sep', 'section', '1. Feminist Ethics: Historical Background'), c('fem-latin-american-sep', 'section', 'Introduction; 1. History')]),
    ],
    relatedPhilosopherIds: ['wollstonecraft', 'beauvoir'],
  },
  {
    id: 'waves',
    title: 'What the wave metaphor hides',
    paragraphs: [
      p('fem-waves-1', 'The familiar sequence of first, second, third, and later “waves” can orient a limited history of movements in the United States and parts of Europe. It can identify clusters around suffrage, mid-century liberation, and later critiques of exclusion. Used as a global master chronology, however, it implies that activism crests, disappears, and returns in uniform generations. It can push labor, antiracist, lesbian, socialist, Indigenous, religious, and community organizing outside the story when those activities do not fit the expected peaks.', [c('fem-overview-sep', 'section', '1. What is Feminism?'), c('fem-waves-nicholson', 'section', 'Feminism in “Waves”: Useful Metaphor or Not?')]),
      p('fem-waves-2', 'The metaphor can also make criticism of earlier feminism look as though it began only with a newly numbered wave. Black feminists, working-class organizers, lesbians, women in colonized societies, and others challenged dominant agendas during periods later narrated as internally unified. A better Atlas uses waves as one explicitly local teaching aid and then adds overlapping genealogies, institutions, texts, political struggles, and regional timelines. “Earlier” and “later” describe chronology; they do not automatically mean less and more inclusive.', [c('fem-waves-nicholson', 'section', 'Feminism in “Waves”: Useful Metaphor or Not?'), c('fem-politics-sep', 'section', '1. Historical Context and Developments')]),
    ],
  },
  {
    id: 'ethics-care',
    title: 'Ethics, care, dependency, and power',
    paragraphs: [
      p('fem-ethics-1', 'Feminist ethics asks how gendered power shapes moral concepts, practices, and the circumstances in which people act. It criticizes theories that present a privileged subject as though it were universal, that ignore violence or unpaid labor in supposedly private life, or that treat dependency as an exception to normal agency. Feminist ethicists also revise and use deontological, consequentialist, virtue, pragmatist, phenomenological, and nonideal approaches. The field is not equivalent to one “ethic of care.”', [c('fem-ethics-sep', 'section', 'Introduction; 2. Themes in feminist ethics'), c('fem-overview-sep', 'section', '4. Interventions in Philosophy')]),
      p('fem-ethics-2', 'Care ethics and relational accounts challenge pictures of persons as wholly independent choosers. They make vulnerability, attachment, caregiving, and unequal divisions of labor philosophically visible. Internal critics warn against treating care as naturally feminine, celebrating sacrifice under unjust conditions, or overlooking disabled people and paid care workers. Feminist ethics therefore asks both what good care requires and how institutions distribute its work, authority, risk, and benefits. Attention to material conditions connects intimate life to public policy and political economy.', [c('fem-ethics-sep', 'section', '2.2 Ethic of care and relational ethics'), c('fem-disability-sep', 'section', '6. Ethics and Inclusion; 7.1 Caregiving')]),
    ],
    relatedBranchIds: ['ethics', 'political-philosophy'],
  },
  {
    id: 'epistemology',
    title: 'Knowledge, standpoint, and objectivity',
    paragraphs: [
      p('fem-epistemology-1', 'Feminist epistemology studies how social position and gendered power affect who is recognized as a knower, which questions are pursued, how evidence is interpreted, and whose testimony receives authority. To call knowledge situated is not to say that every belief is equally true or that identity guarantees insight. It is to reject the fiction that inquiry occurs from nowhere. Social locations can produce blind spots or resources for criticism, and claims remain answerable to evidence, argument, and responsive communities.', [c('fem-epistemology-sep', 'section', '1. Situated Knowers'), c('fem-overview-sep', 'section', '4. Interventions in Philosophy')]),
      p('fem-epistemology-2', 'Standpoint theories, feminist empiricisms, and postmodern approaches have disagreed and changed through mutual criticism. Some emphasize how marginalized positions can reveal relations obscured from dominant standpoints; some focus on reforming empirical methods and critical communities; some resist stable universal subjects. Feminist philosophers of science debate the role of values, ideals of objectivity, and standards for criticism. These projects do not license suppressing inconvenient evidence: several explicitly defend open, diverse, and publicly answerable practices of inquiry.', [c('fem-epistemology-sep', 'section', '2–8; 10. External Criticisms')]),
    ],
    relatedBranchIds: ['epistemology', 'philosophy-of-science'],
  },
  {
    id: 'political',
    title: 'Making power in ordinary life visible',
    paragraphs: [
      p('fem-political-1', 'Feminist political philosophy widened the domain of political analysis beyond states and formal offices. Families, workplaces, reproduction, sexuality, care, violence, and civil society distribute power and shape a person’s effective freedom. The claim that personal life is political does not mean that every private choice should be governed by the state. It means that a public/private boundary can hide domination, unpaid work, dependency, and institutional rules from scrutiny.', [c('fem-politics-sep', 'section', 'Introduction; 1. Historical Context and Developments')]),
      p('fem-political-2', 'Liberal, radical, socialist, Marxist, materialist, poststructuralist, care-centered, intersectional, transnational, decolonial, Indigenous, and democratic feminisms offer competing diagnoses and aims. Debates concern rights and redistribution, capitalism and social reproduction, universal norms and cultural difference, abolition and institutional reform, sexual politics, family, state power, and the meaning of freedom. These families overlap, and no short taxonomy captures every regional or historical current. A neutral-looking list becomes misleading if it hides which debates generated its categories.', [c('fem-politics-sep', 'section', '2. Contemporary Approaches and Debates')]),
    ],
    relatedBranchIds: ['political-philosophy'],
  },
  {
    id: 'intersectionality',
    title: 'Intersectionality and Black feminist critique',
    paragraphs: [
      p('fem-intersection-1', 'Kimberlé Crenshaw’s 1989 legal analysis showed how a single-axis framework could make Black women’s discrimination claims difficult to recognize when law searched separately for race discrimination modeled on Black men or sex discrimination modeled on white women. Intersectionality names an analytic problem about interacting structures and the categories used to perceive them. It is not merely a checklist of personal identities, and it did not arise from abstract diversity management.', [c('fem-crenshaw', 'section', 'Introduction; I. The Antidiscrimination Framework'), c('fem-politics-sep', 'section', '2.6 Intersectional Feminisms')]),
      p('fem-intersection-2', 'Black feminist theory both precedes and exceeds the coinage of intersectionality. It has analyzed race, gender, class, sexuality, labor, family, state violence, culture, and political organizing as mutually shaping. Intersectional approaches have since traveled across disciplines and regions, producing productive extensions and disputes about method, scale, identity, structure, and appropriation. A branch page should attribute particular concepts and texts while avoiding the claim that one framework speaks for every Black feminist or every multiply marginalized person.', [c('fem-politics-sep', 'section', '1. Historical Context; 2.6 Intersectional Feminisms'), c('fem-ethics-sep', 'section', '2.3 Intersectionality')]),
    ],
    relatedPhilosopherIds: ['angela-davis', 'bell-hooks'],
  },
  {
    id: 'sex-gender',
    title: 'Sex, gender, and the category of women',
    paragraphs: [
      p('fem-gender-1', 'Feminist philosophers have used distinctions between sex and gender to challenge the idea that social roles follow inevitably from biology. They have also criticized simple versions of that distinction. Sex classification is not philosophically transparent, gender is not uniform across societies, and embodiment cannot be cleanly separated from social meaning. Competing accounts treat gender through social position, identity, norms, relations, performance, or other structures. No single definition functions as the uncontested feminist answer.', [c('fem-gender-sep', 'section', '1. The sex/gender distinction; 2–4')]),
      p('fem-gender-2', 'The question “who are women?” has political and metaphysical stakes. Some accounts seek a category capable of naming patterned subordination or organizing solidarity; others warn that a supposedly universal woman reproduces racial, colonial, class, heterosexual, able-bodied, or nontrans assumptions. Nominalist, realist, ameliorative, and coalition-based proposals answer different purposes. Responsible exposition distinguishes descriptive claims, political aims, and linguistic choices rather than presenting a contested definition as a gatekeeping fact.', [c('fem-gender-sep', 'section', '4. Women as a Group; 5. Beyond the Binary'), c('fem-politics-sep', 'section', '1. Historical Context and Developments')]),
    ],
  },
  {
    id: 'trans-feminism',
    title: 'Trans feminism, conflict, and solidarity',
    paragraphs: [
      p('fem-trans-1', 'Feminist and trans theory have a fraught shared history that includes exclusion, pathologization, critique, coalition, and new philosophical work. Trans feminist arguments challenge accounts that treat nontrans experience as the unmarked basis of womanhood or reduce trans lives to examples for someone else’s theory. They also develop questions about first-person authority, embodiment, oppression, identity, medical institutions, violence, and resistant social worlds. Trans philosophy is not one position, and neither is feminism.', [c('fem-trans-sep', 'section', 'Introduction; 3–6')]),
      p('fem-trans-2', 'Contemporary disputes about gender categories, self-identification, material conditions, law, and institutional policy are real and often politically urgent. An educational page should neither erase disagreement nor stage trans people’s existence as an abstract debate. It can identify arguments, historical contexts, and consequences; distinguish conceptual analysis from empirical or policy claims; include trans feminist scholarship as scholarship rather than a side note; and avoid presenting the most polarizing Euro-American controversy as the global shape of feminist thought.', [c('fem-trans-sep', 'section', '5–9'), c('fem-ethics-sep', 'section', '2.1 Gender binarism, essentialism, and transfeminism')]),
    ],
  },
  {
    id: 'global-decolonial',
    title: 'Transnational, decolonial, and Indigenous challenges',
    paragraphs: [
      p('fem-global-1', 'Transnational and decolonial feminisms examine how colonial histories, borders, global capitalism, development policy, migration, war, religion, and cultural translation shape gendered power. They criticize narratives in which a universal Western subject diagnoses and rescues an undifferentiated “other woman.” They also debate universal norms, local authority, solidarity, and the danger that respect for culture can shield domination. The alternatives are not simply Western universalism or cultural silence.', [c('fem-politics-sep', 'section', '2.7 Transnational, Decolonial, and Indigenous Feminisms'), c('fem-latin-american-sep', 'section', 'Introduction; 2. Key Issues and Debates')]),
      p('fem-global-2', 'Indigenous feminisms arise from particular nations, lands, legal orders, kinship systems, and colonial histories; the plural matters. Their concepts should not be absorbed into a generic spirituality or diversity category. Latin American and Caribbean feminisms likewise contain multiple positions shaped by distinct histories of colonialism, enslavement, racial formation, religion, dictatorship, neoliberalism, and resistance. Cross-regional comparison is valuable when it names location, translation, and power instead of arranging every movement on a Euro-American wave timeline.', [c('fem-politics-sep', 'section', '2.7 Transnational, Decolonial, and Indigenous Feminisms'), c('fem-latin-american-sep', 'section', 'Introduction; 1–3')]),
    ],
  },
  {
    id: 'disability',
    title: 'Disability, embodiment, and dependence',
    paragraphs: [
      p('fem-disability-1', 'Feminist philosophy of disability examines how ideals of normalcy, independence, productivity, beauty, rational agency, and bodily control can exclude disabled people. Feminist work on embodiment, standpoint, care, and social construction supplied important resources, while disability scholars also exposed limits in feminist theories that treated health, capacity, or maternal roles as unproblematic. The relationship is therefore critical and reciprocal rather than a simple application of an already complete feminist method.', [c('fem-disability-sep', 'section', '2. The Importance and Relevance of Feminist Philosophy; 4–6')]),
      p('fem-disability-2', 'Dependency is a human condition distributed across lives, not a rare failure outside political theory. Yet dependence can be organized through unjust institutions, and celebrating care can conceal coercion or unpaid labor. Reproductive politics can place feminist and disability claims in tension when disabled lives are framed only as burdens or when women’s bodily autonomy is ignored. A careful account keeps disabled people’s agency, access, testimony, and diverse experiences visible while refusing a single “disability perspective.”', [c('fem-disability-sep', 'section', '6. Ethics and Inclusion; 7. Applications'), c('fem-ethics-sep', 'section', '2.2–2.4')]),
    ],
  },
  {
    id: 'methods-canon',
    title: 'Methods, canons, and philosophical institutions',
    paragraphs: [
      p('fem-methods-1', 'Feminist work changes philosophy at several levels. It can recover neglected authors, reinterpret canonical texts, criticize a concept built from an exclusionary example, introduce a problem previously dismissed as private, or reconstruct a method so that different evidence becomes visible. These projects are not interchangeable. Adding women to a reading list does not by itself answer a critique of the category of reason, and revising a concept does not make historical recovery unnecessary. Editorially, the kind of intervention should be named rather than gathered under the vague promise of “adding perspective.”', [c('fem-overview-sep', 'section', '2. Feminist Scholarship; 3. Approaches; 4. Interventions in Philosophy')]),
      p('fem-methods-2', 'The institution of philosophy is also an object of analysis. Admission, hiring, citation, syllabus design, professional style, harassment, informal networks, and judgments about what counts as a central question can shape whose work becomes authoritative. Institutional criticism does not show that every excluded argument was sound or every canonical work worthless. It asks whether the procedures selecting problems and experts have been neutral in practice, and it connects intellectual standards with the social conditions needed for disagreement to be informed rather than merely formal.', [c('fem-overview-sep', 'section', '2. Feminist Scholarship; 4. Interventions in Philosophy'), c('fem-epistemology-sep', 'section', '1. Situated Knowers; 6–8')]),
    ],
  },
  {
    id: 'autonomy-agency',
    title: 'Autonomy, agency, and nonideal conditions',
    paragraphs: [
      p('fem-autonomy-1', 'Feminist philosophers have criticized models of autonomy that picture a person as self-made, socially detached, and free whenever no one issues a direct command. Relational approaches examine how family, education, economic dependence, violence, social norms, and available narratives shape the capacities through which choices are formed and acted upon. This need not replace individual agency with social determination. It asks what relationships and institutions support reflection, self-trust, practical authority, and meaningful options, while recognizing that people exercise agency under conditions they did not choose.', [c('fem-ethics-sep', 'section', '2.2 Ethic of care and relational ethics; 2.4.3 Moral contractarianism'), c('fem-politics-sep', 'section', '2. Contemporary Approaches and Debates')]),
      p('fem-autonomy-2', 'Nonideal theory begins from injustice as it is reproduced rather than from perfectly compliant institutions alone. It examines power, history, adaptive preferences, resistance, compromise, and the unequal risks attached to action. The approach raises its own questions: how should theory identify injustice without a normative standard, when does attention to feasibility become resignation, and whose account of lived constraint guides the diagnosis? Feminist philosophers answer differently. The shared lesson is that a recommendation can be formally universal yet practically unavailable to people whose material and social conditions the theory leaves unexamined.', [c('fem-ethics-sep', 'section', 'Introduction; 2.4 Feminist criticisms and expansions of traditional moral theories'), c('fem-politics-sep', 'section', '1–2')]),
    ],
    relatedBranchIds: ['ethics', 'political-philosophy'],
  },
  {
    id: 'embodiment-reproduction',
    title: 'Embodiment, reproduction, and social reproduction',
    paragraphs: [
      p('fem-embodiment-1', 'Embodiment enters feminist philosophy not as a single celebration of “the body” but as a set of disputes about lived experience, medical classification, race, disability, sexuality, pregnancy, aging, appearance, vulnerability, and social meaning. A body is neither raw matter outside interpretation nor merely a text written by culture. Different methods emphasize phenomenology, material processes, discourse, political economy, or scientific practice. Responsible exposition states which dimension an argument addresses and avoids treating the experience of one socially dominant group as the universal female body.', [c('fem-overview-sep', 'section', '5. Topics'), c('fem-gender-sep', 'section', '1–5'), c('fem-disability-sep', 'section', '4–7')]),
      p('fem-embodiment-2', 'Reproduction is similarly broader than an isolated decision. Feminist analysis considers bodily autonomy, contraception, abortion, pregnancy, birth, parenting, infertility, assisted reproduction, disability, adoption, population policy, and the labor that sustains households and communities. Reproductive justice frameworks connect legal choice with the material ability to have children, not have children, and raise families safely, though traditions formulate these concerns differently. Tensions remain among autonomy, disability critique, medical authority, family regulation, religious commitments, and unequal exposure to state intervention.', [c('fem-politics-sep', 'section', '2. Contemporary Approaches and Debates'), c('fem-ethics-sep', 'section', '2. Themes in feminist ethics'), c('fem-disability-sep', 'section', '6–7')]),
    ],
  },
  {
    id: 'violence-law-state',
    title: 'Violence, law, and ambivalence about the state',
    paragraphs: [
      p('fem-violence-1', 'Feminist philosophy helped make domestic abuse, sexual violence, harassment, and coercive control visible as political and ethical problems rather than private misfortunes. The analysis concerns credibility, consent, bodily integrity, economic dependence, institutional complicity, and the social conditions under which refusal can be expressed or heard. Legal recognition can provide language and remedies, but law alone does not eliminate unequal power. Policies can fail when they assume one model victim, ignore disability or immigration status, or require people to seek protection from institutions they reasonably distrust.', [c('fem-politics-sep', 'section', '1. Historical Context and Developments; 2. Contemporary Approaches and Debates'), c('fem-ethics-sep', 'section', '2. Themes in feminist ethics')]),
      p('fem-violence-2', 'This produces disagreement about policing, punishment, and the state. Some feminists seek stronger criminal enforcement and civil protection; others argue that carceral responses can intensify racialized violence, family separation, surveillance, or precarity and advocate prevention, material support, restorative practices, or abolitionist transformation. No formula resolves every case. Philosophical assessment must compare harms, institutional histories, agency, accountability, and feasible protections instead of assuming that more punishment always equals more safety or that criticism of punishment makes immediate danger unreal.', [c('fem-politics-sep', 'section', '2. Contemporary Approaches and Debates; 2.6–2.7'), c('fem-ethics-sep', 'section', 'Introduction; 2.3 Intersectionality')]),
    ],
    relatedBranchIds: ['political-philosophy', 'ethics'],
  },
  {
    id: 'language-objectification',
    title: 'Language, objectification, and social meaning',
    paragraphs: [
      p('fem-language-1', 'Language can describe unequal relations and help constitute them. Feminist philosophers ask how slurs, pornography, silencing, conversational authority, naming practices, and apparently generic terms affect what people can do with words and how they are recognized. The claim is not that language mechanically creates every material condition. It is that speech acts operate within institutions and conventions: an utterance may authorize, subordinate, exclude, warn, promise, or fail depending on who speaks, who receives uptake, and what background power gives the act force.', [c('fem-overview-sep', 'section', '4. Interventions in Philosophy; 5. Topics'), c('fem-epistemology-sep', 'section', '1. Situated Knowers; 6–8')]),
      p('fem-language-2', 'Objectification theories likewise form a family rather than one test. They examine ways a person may be treated as an instrument, denied autonomy or subjectivity, made interchangeable, reduced to body or appearance, or positioned for another’s use. Context matters: depiction, desire, labor, medicine, and violence do not instantiate one identical relation. Feminists disagree about pornography, sexual representation, agency, consent, and whether some objectifying attitudes can be transformed. A useful account identifies the mechanism and harm claimed instead of treating discomfort as a sufficient definition.', [c('fem-overview-sep', 'section', '5. Topics'), c('fem-ethics-sep', 'section', '2. Themes in feminist ethics')]),
    ],
    relatedBranchIds: ['philosophy-of-language', 'ethics'],
  },
  {
    id: 'science-technology',
    title: 'Science, medicine, and technology',
    paragraphs: [
      p('fem-science-1', 'Feminist philosophy of science distinguishes several sites where values and social organization can matter: which questions receive funding, how categories are defined, who is recruited into a study, what counts as a significant difference, how uncertainty is communicated, and whose testimony shapes application. Pointing to these decisions does not imply that evidence is whatever politics prefers. It motivates stronger controls, more representative inquiry, transparent assumptions, and critical communities able to detect errors that homogeneous expertise may normalize.', [c('fem-epistemology-sep', 'section', '3–9'), c('fem-overview-sep', 'section', '4. Interventions in Philosophy')]),
      p('fem-science-2', 'Contemporary technologies extend those questions. Automated classification can inherit historical data and rigid categories; workplace systems can redistribute surveillance and care burdens; medical tools can encode assumptions about normal bodies; online platforms can amplify harassment while also enabling community. Feminist analysis does not supply a single verdict on “technology.” It asks who defines the problem, whose labor remains invisible, which groups bear error, what appeal is possible, and how design interacts with law and political economy. Those questions connect epistemology with concrete institutional responsibility.', [c('fem-epistemology-sep', 'section', '1; 3–9'), c('fem-disability-sep', 'section', '4–7'), c('fem-politics-sep', 'section', '2. Contemporary Approaches and Debates')]),
    ],
    relatedBranchIds: ['philosophy-of-science', 'epistemology', 'political-philosophy'],
  },
  {
    id: 'solidarity-coalition',
    title: 'Solidarity without a single subject',
    paragraphs: [
      p('fem-coalition-1', 'A plural field still needs ways to act together. Coalition models treat solidarity as a political and intellectual achievement rather than the automatic result of sharing one identity. Participants may cooperate because structures and projects connect their interests, while retaining different histories, risks, and analyses. This approach can keep difference visible without concluding that communication is impossible. It also makes accountability practical: a coalition can revise its terms when some members bear costs, disappear from leadership, or find that a supposedly shared goal was defined through someone else’s experience.', [c('fem-politics-sep', 'section', '2.6 Intersectional Feminisms; 2.7 Transnational, Decolonial, and Indigenous Feminisms'), c('fem-ethics-sep', 'section', '2.3 Intersectionality')]),
      p('fem-coalition-2', 'Coalition does not solve every conflict by changing the vocabulary. Groups can disagree about policy, categories, institutions, or fundamental values, and power differences can survive inclusive procedure. Nor does criticism from within a movement prove that collective action has failed. It can identify who was treated as representative and force a clearer statement of aims. Black feminist, trans feminist, disability, Indigenous, decolonial, and other interventions have often functioned in this reconstructive way: not merely asking entry into an unchanged framework, but changing the questions, subjects, and measures of success.', [c('fem-politics-sep', 'section', '1–2.7'), c('fem-trans-sep', 'section', '5–9'), c('fem-disability-sep', 'section', '2; 6–7')]),
      p('fem-coalition-3', 'Universal claims remain possible, but they must be tested against the histories and exclusions hidden by their formulation. A right may be stated for everyone while access depends on money, citizenship, bodily capacity, safety, or recognition. Conversely, attention to difference need not abandon judgments about violence, domination, or dignity. Feminist debates over universalism ask how norms can travel, who participates in articulating them, and what institutions make them usable. The answer is a contested practice of translation and revision, not a choice between a view from nowhere and isolated local worlds.', [c('fem-politics-sep', 'section', '2.7 Transnational, Decolonial, and Indigenous Feminisms'), c('fem-latin-american-sep', 'section', '2. Key Issues and Debates'), c('fem-ethics-sep', 'section', '2. Themes in feminist ethics')]),
    ],
  },
  {
    id: 'debates-reading',
    title: 'Internal disagreement and a responsible reading path',
    paragraphs: [
      p('fem-reading-1', 'Feminist philosophers disagree about capitalism, law, the state, pornography, sex work, reproduction, family, violence, universalism, religion, gender categories, trans inclusion, carceral policy, disability, and strategies for change. Some disputes arise from incompatible principles; others from different histories, empirical assumptions, or political priorities. “Feminism says” is therefore usually too broad. Name the author, tradition, setting, and target, and distinguish a family resemblance from a consensus claim.', [c('fem-politics-sep', 'section', '2. Contemporary Approaches and Debates'), c('fem-ethics-sep', 'section', '2. Themes in feminist ethics'), c('fem-trans-sep', 'section', '5–9')]),
      p('fem-reading-2', 'A strong reading path pairs genealogy with problems. Read Wollstonecraft as a situated primary text, then Crenshaw’s legal intervention and a Black feminist statement or book. Add a field overview, then specialist work in ethics, epistemology, political philosophy, gender, trans philosophy, disability, and at least one regional or decolonial genealogy. Compare disagreements rather than collecting representative slogans. Ask whose experience is treated as typical, what institution produces the problem, which evidence supports the account, and what action the proposed concept makes possible.', [c('fem-wollstonecraft', 'chapter', 'Introduction; chapters 2 and 12'), c('fem-crenshaw', 'work', 'Demarginalizing the Intersection of Race and Sex'), c('fem-overview-sep', 'section', '3–5'), c('fem-latin-american-sep', 'section', '3. Latin American Feminist Philosophy')]),
    ],
    relatedPhilosopherIds: ['wollstonecraft', 'beauvoir', 'judith-butler', 'angela-davis', 'bell-hooks'],
  },
];

